const { Input } = __require("js/input.js");
const { TouchControls } = __require("js/touch_controls.js");
const { Game } = __require("js/game.js");
const { Renderer } = __require("js/renderer.js");
const { AudioSystem } = __require("js/audio.js");
const { ACTIVE_LEVEL_CONFIG } = __require("js/levels.js");
const { FIXED_DT, FixedTimestep } = __require("js/fixed_timestep.js");
const { PerformanceMonitor } = __require("js/performance.js");

const canvas = document.querySelector("#game");
canvas.width = CONFIG.WIDTH; canvas.height = CONFIG.HEIGHT;

// Assets são opcionais: se um PNG estiver ausente, placeholders ainda funcionam.
await loadAssets();

const input = new Input();
const game = new Game(input);
const renderer = new Renderer(canvas);
const touchControls = new TouchControls(input, document.querySelector(".game-shell") || canvas, () => game.state, window,
  () => Boolean(game.tutorialPopups.page));
renderer.touchControls = touchControls;
const audio = new AudioSystem();
game.audio = audio;
audio.sync(game);

console.log("[Level Lock] 13 fases carregadas:", ACTIVE_LEVEL_CONFIG.ROOM_ORDER.join(" -> "));

// ===========================================================================
// RAF DINÂMICO & AMOSTRAGEM DIAGNÓSTICA DA TAXA DO MONITOR (Hz)
// ===========================================================================
// Esta estimativa existe somente para telemetria. Ela nunca agenda render,
// altera o fixed timestep ou limita requestAnimationFrame.
const STANDARD_REFRESH_RATES = [60, 75, 90, 100, 120, 144, 165, 180, 200, 240, 280, 360];
const MAX_REFRESH_SAMPLES = 40;
const refreshSamples = new Float64Array(MAX_REFRESH_SAMPLES);
const sortedSamples = new Float64Array(MAX_REFRESH_SAMPLES);
let sampleIndex = 0;
let sampleCount = 0;
let detectedMonitorHz = 60;
let hzCalibrationCountdown = 8;

function sampleMonitorHz(deltaMs) {
  if (deltaMs < 2 || deltaMs > 50) return;
  refreshSamples[sampleIndex] = deltaMs;
  sampleIndex = (sampleIndex + 1) % MAX_REFRESH_SAMPLES;
  if (sampleCount < MAX_REFRESH_SAMPLES) sampleCount++;

  hzCalibrationCountdown--;
  if (hzCalibrationCountdown <= 0 && sampleCount >= 8) {
    hzCalibrationCountdown = 30;
    for (let i = 0; i < sampleCount; i++) {
      sortedSamples[i] = refreshSamples[i];
    }
    for (let i = 1; i < sampleCount; i++) {
      const val = sortedSamples[i];
      let j = i - 1;
      while (j >= 0 && sortedSamples[j] > val) {
        sortedSamples[j + 1] = sortedSamples[j];
        j--;
      }
      sortedSamples[j + 1] = val;
    }
    const medianDelta = sortedSamples[Math.floor(sampleCount / 2)];
    const rawHz = 1000 / medianDelta;

    let matchedHz = Math.round(rawHz);
    for (let i = 0; i < STANDARD_REFRESH_RATES.length; i++) {
      const stdHz = STANDARD_REFRESH_RATES[i];
      if (Math.abs(rawHz - stdHz) <= 3.5) {
        matchedHz = stdHz;
        break;
      }
    }

    detectedMonitorHz = Math.max(30, Math.min(1000, matchedHz));
    game.monitorHz = detectedMonitorHz;
  }
}

// A simulação permanece em 120 Hz. Cada oportunidade de RAF produz um render,
// seja a apresentação 60, 90, 144, 240, 360 Hz ou qualquer outra cadência.
const fixedTimestep = new FixedTimestep();
const performanceMonitor = new PerformanceMonitor();
let previous = performance.now();
let nextTelemetryUpdate = 0;
const telemetryCache = Object.create(null);
const telemetryPayload = {
  state: "", room: "", hp: 0, dash: false, key: false,
  boss: "none", bossHp: 0,
  playerX: 0, playerY: 0, bossX: 0,
  facing: 1, cameraY: 0,
  vsync: "on", monitorHz: 60, fps: 60,
};

let rafId = null;
let isDormant = false;

function enterDormancy() {
  if (isDormant) return;
  if (game.state === GAME_STATES.PLAYING) {
    game.pause();
  }
  audio.suspend();
  renderer.render(game);
  isDormant = true;
  if (typeof cancelAnimationFrame === "function" && rafId !== null) {
    cancelAnimationFrame(rafId);
    rafId = null;
  }
}

function wakeFromDormancy() {
  if (!isDormant) return;
  isDormant = false;
  previous = performance.now();
  fixedTimestep.accumulator = 0;
  if (game.state !== GAME_STATES.PAUSED) {
    audio.resume();
  }
  if (!rafId && typeof requestAnimationFrame === "function") {
    rafId = requestAnimationFrame(loop);
  }
}

function loop(now) {
  if (isDormant) {
    rafId = null;
    return;
  }
  const measuring = performanceMonitor.enabled;
  const frameStarted = measuring ? performance.now() : 0;
  const deltaMs = Math.max(0, now - previous);
  const frameDelta = deltaMs / 1000;
  previous = now;

  // Calibra a taxa do monitor em tempo real
  if (deltaMs > 0) {
    sampleMonitorHz(deltaMs);
  }

  const rawInstantFps = deltaMs > 0 ? 1000 / deltaMs : game.fps;
  game.fps += (rawInstantFps - game.fps) * 0.08;
  if (measuring) performanceMonitor.recordPacing(deltaMs);

  const stepResult = fixedTimestep.advance(frameDelta, fixedUpdate);

  audio.sync(game);
  const renderStarted = measuring ? performance.now() : 0;
  renderer.render(game, stepResult.alpha);
  if (measuring) performanceMonitor.recordRender(performance.now() - renderStarted);

  // Telemetria é útil para demonstração, mas não precisa causar mutações no DOM 60 vezes por segundo.
  if (now >= nextTelemetryUpdate) {
    nextTelemetryUpdate = now + 250;
    telemetryPayload.state = game.state;
    telemetryPayload.room = game.roomId;
    telemetryPayload.hp = game.player.hp;
    telemetryPayload.dash = game.player.canDash;
    telemetryPayload.key = game.keyCollected;
    telemetryPayload.boss = game.boss?.state || "none";
    telemetryPayload.bossHp = game.boss?.hp ?? 0;
    telemetryPayload.playerX = Math.round(game.player.x);
    telemetryPayload.playerY = Math.round(game.player.y);
    telemetryPayload.bossX = Math.round(game.boss?.x ?? 0);
    telemetryPayload.facing = game.player.facing;
    telemetryPayload.cameraY = game.camera.renderY;
    telemetryPayload.vsync = game.vsync ? "on" : "off";
    telemetryPayload.monitorHz = Math.round(game.monitorHz);
    telemetryPayload.fps = Math.round(game.fps);
    updateTelemetry(canvas, telemetryCache, telemetryPayload);
  }
  if (!isDormant && typeof requestAnimationFrame === "function") {
    rafId = requestAnimationFrame(loop);
  } else {
    rafId = null;
  }
  if (measuring) performanceMonitor.recordFrame(performance.now() - frameStarted, stepResult.updates);
}

function fixedUpdate(dt) {
  if (!performanceMonitor.enabled) {
    game.update(dt);
    return;
  }
  const started = performance.now();
  game.update(dt);
  performanceMonitor.recordUpdate(performance.now() - started);
}
if (typeof requestAnimationFrame === "function") {
  rafId = requestAnimationFrame(loop);
}

if (typeof document !== "undefined") {
  document.addEventListener?.("visibilitychange", () => {
    if (document.hidden) {
      enterDormancy();
    } else {
      wakeFromDormancy();
    }
    previous = performance.now();
    fixedTimestep.accumulator = 0;
  });
}

if (typeof window !== "undefined") {
  window.addEventListener?.("blur", () => {
    enterDormancy();
  });
  window.addEventListener?.("focus", () => {
    wakeFromDormancy();
  });
  window.addEventListener?.("pointerdown", () => {
    wakeFromDormancy();
  });
  window.addEventListener?.("keydown", () => {
    wakeFromDormancy();
  });
}

