// HOPPER: cada cor possui seus próprios PNGs para permitir edição direta dos
// tons sem filtros ou paletas definidos no código.
function createHopperAnimations(variant) {
  const source = (animation) => `./hopper-${variant}-${animation}.png`;
  return {
    idle: {
      src: source("idle"),
      fps: 8,
      frames: Array.from({ length: 7 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
    jumpstartup: {
      src: source("jumpstartup"),
      fps: 18,
      frames: Array.from({ length: 9 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
    jumpup: {
      src: source("jumpup"),
      fps: 10,
      frames: [{ sx: 0, sy: 0, sw: 96, sh: 32 }],
    },
    jumpfall: {
      src: source("jumpfall"),
      fps: 10,
      frames: Array.from({ length: 5 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
    jumpdown: {
      src: source("jumpdown"),
      fps: 10,
      frames: [{ sx: 0, sy: 0, sw: 96, sh: 32 }],
    },
    jumpland: {
      src: source("jumpland"),
      fps: 16,
      frames: Array.from({ length: 6 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
    hurt: {
      src: source("hurt"),
      fps: 16,
      frames: Array.from({ length: 11 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
    death: {
      src: source("death"),
      fps: 14,
      frames: Array.from({ length: 14 }, (_, i) => ({ sx: i * 96, sy: 0, sw: 96, sh: 32 })),
    },
  };
}

