// A mola vermelha é uma folha de 123×24 px com cinco quadros separados por
// espaços transparentes irregulares. Cada recorte usa apenas os pixels visíveis;
// o renderer centraliza os quadros e mantém todos apoiados pela mesma base.
const springRedFrames = [
  { sx: 0, sy: 11, sw: 22, sh: 13 },
  { sx: 24, sy: 10, sw: 21, sh: 14 },
  { sx: 47, sy: 0, sw: 22, sh: 24 },
  { sx: 74, sy: 3, sw: 22, sh: 21 },
  { sx: 102, sy: 8, sw: 21, sh: 16 },
];
function createSpringSheetConfig(src) {
  return {
    src,
    category: "speed",
    animations: {
      idle: { fps: 20, frames: [springRedFrames[4]] },
      bounce: { fps: 20, frames: springRedFrames },
    },
  };
}
// Cada variação visual aponta para um PNG independente. speed_spring_red é
// mantido para compatibilidade com o tipo físico legado da mola vermelha.
AssetManager.registerSpritesheet("speed_spring_yellow", createSpringSheetConfig("./spring_yellow.png"));
AssetManager.registerSpritesheet("speed_spring_pink", createSpringSheetConfig("./spring_pink.png"));
AssetManager.registerSpritesheet("speed_spring_red", createSpringSheetConfig("./spring_red.png"));
const diagonalSpringFrames = Array.from({ length: 5 }, (_, index) => ({
  sx: index * 36, sy: 0, sw: 36, sh: 36,
}));
function createDiagonalSpringSheetConfig(src) {
  return {
    src,
    category: "speed",
    animations: {
      idle: { fps: 20, frames: [diagonalSpringFrames[4]] },
      bounce: { fps: 20, frames: diagonalSpringFrames },
    },
  };
}
for (const direction of ["right", "left"]) {
  for (const color of ["yellow", "pink", "red"]) {
    AssetManager.registerSpritesheet(
      `speed_spring_diagonal_${direction}_${color}`,
      createDiagonalSpringSheetConfig(`./spring_diagonal_${direction}_${color}.png`),
    );
  }
}
AssetManager.register("speed_spring_diagonal", { src: "./spring_diagonal.png", frameWidth: 24, frameHeight: 16, category: "speed" });
