    captureEntityPosition(this.player);
    for (let i = 0; i < this.enemies.length; i++) captureEntityPosition(this.enemies[i]);
    for (let i = 0; i < this.speedObjects.length; i++) captureEntityPosition(this.speedObjects[i]);
