    const journeyProgress = smoothstep(2.05, 4.85, introTime);
    const journeyY = 960 * journeyProgress;
    const cameraY = -320 * (1 - descent) + journeyY;
    // A primeira fileira totalmente de caverna começa em y=576. Ela entra na
