    const caveBackdropVisible = journeyY >= 360;
    const logoReveal = smoothstep(0.85, 1.55, introTime);
    const promptReveal = smoothstep(1.3, 1.95, introTime);

    // Cenário da tela inicial: céu e prédios externos, com movimento independente
    // em cada camada de profundidade.
    const titleCameraX = game.time * 26;
    const titleView = { x: titleCameraX, y: cameraY, w: CONFIG.WIDTH, h: CONFIG.HEIGHT };
    const skyAsset = ASSETS.world?.sky;
    const skyImage = skyAsset?.loaded && skyAsset.image;
    const buildingSlices = ASSETS.world?.buildingSlices;
    const uiRenderer = activeUiRenderer;
    const uiCtx = uiRenderer?.uiCtx;
    const useSmoothBackdrop = Boolean(uiCtx && uiRenderer?.uiCanvas?.width > 0 && uiRenderer?.uiCanvas?.height > 0);
    ctx.fillStyle = "#000000";
