        uiCtx.shadowColor = "rgba(0, 0, 0, 0.75)";
        uiCtx.shadowBlur = Math.round(10 * ((scaleX + scaleY) / 2));
        uiCtx.shadowOffsetY = Math.round(4 * scaleY);
        uiCtx.imageSmoothingEnabled = true;
