        ctx.shadowBlur = 10;
        ctx.shadowOffsetY = 4;
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = "high";
        ctx.drawImage(logo.image, 0, 0, logo.frameWidth, logo.frameHeight, logoX, logoY, logoW, logoH);
        ctx.restore();
        ctx.imageSmoothingEnabled = false;
