    ctx.save();
    ctx.globalAlpha = promptReveal;
    const promptPulse = (Math.sin(game.time * 3.4) + 1) / 2;
    const promptColor = promptPulse > 0.45 ? "#f0f6fc" : "#7b93ab";
    const startPrompt = Object.keys(game.rooms || ROOMS).length === 0
