    ctx.strokeStyle = "#fff14b"; for (const b of game.player.attackBoxes) ctx.strokeRect(b.x, b.y, b.w, b.h);
    if (game.player.shieldBox) { const b = game.player.shieldBox; ctx.strokeStyle = "#70e7f2"; ctx.strokeRect(b.x, b.y, b.w, b.h); }
    ctx.strokeStyle = "#ff5a64"; for (const e of game.enemies) ctx.strokeRect(e.x, e.y, e.w, e.h);
    ctx.strokeStyle = "#6dff83"; for (const s of game.room.solids) ctx.strokeRect(s.x, s.y, s.w, s.h);
