      AssetManager.drawSpriteFrame(ctx, asset, "idle", frameIndex, x, y, iconW, iconH);

      if (keyHint) {
        text(ctx, keyHint, x + Math.round(iconW / 2), y + iconH + 6, "center", 7, isReady ? "#9cb1c9" : "#4a5d73");
      }
      return;
