  const grid = ACTION_ICONS[iconKey];
  const palette = ACTION_PALETTES[iconKey];
  if (!grid || !palette) return;

  // Dimensões do grid
  const gridRows = grid.length;
  const gridCols = grid[0].length;
  // Centraliza o grid de fallback no slot
  const offsetX = Math.round((iconW - gridCols) / 2);
  const offsetY = Math.round((iconH - gridRows) / 2);

